/**
 * Base-notation cases measured on the pinned oracle (`~/ruby_gems/plurimath-oracle`
 * at 00c52783, v0.11.6), one row per `(value, formatter)`. Each row is
 * `[value, formatter, expected]`.
 *
 * The command, per row (the formatter's options are the snake_case spelling of
 * the camelCase keys below; `hexCapital: "true"` is the gem's `:true`):
 *
 *   BUNDLE_GEMFILE=~/ruby_gems/plurimath-oracle/Gemfile mise x -- bundle exec ruby -e '
 *     require "plurimath"
 *     f  = Plurimath::Formatter::Standard.new(locale: "en", options: OPTIONS, precision: PRECISION)
 *     fo = Plurimath::Math::Formula.new([Plurimath::Math::Number.new(VALUE)])
 *     puts fo.to_asciimath(formatter: f), fo.to_latex(formatter: f), fo.to_html(formatter: f),
 *          fo.to_unicodemath(formatter: f), fo.to_mathml(formatter: f)'
 *
 * `expected` is one string when all four text targets answer it and MathML
 * answers `<mn>` of it — every number with no base, and every base given a
 * `basePrefix` or `basePostfix`, which renders as literal text. Otherwise the
 * number has a semantic base (a base other than 10, neither affix given), each
 * target draws it its own way, and `expected` holds the five answers, with
 * `mathml` the inside of `<mstyle displaystyle="true">`, whitespace between
 * tags removed. Many values and options come from the gem's own
 * `spec/plurimath/number_formatter_spec.rb` ("testing base conversion
 * arguments"), rerun through `Formatter::Standard` — the class the `formatter:`
 * option mirrors — whose fraction grouping default differs from the base
 * `NumberFormatter` those examples use, so the expected strings are what
 * Standard answered, not the spec's.
 */

import type { FormatterOptions } from "../../src/formatting/index";

export interface PerTarget {
  readonly asciimath: string;
  readonly latex: string;
  readonly html: string;
  readonly unicodemath: string;
  readonly mathml: string;
}

