/**
 * Options the gem refuses, measured the same way. The gem raises on the call
 * that renders the number — `UnsupportedBase` from `BaseNotation.validate!`,
 * `ConfigurationError` from `FormatOptions` — and `Formula#to_*` then rescues
 * it and raises `ParseError` ("Failed to parse the following formula"), so the
 * class here is the CAUSE's. That `ParseError` is a render-time failure
 * reported under a parse name; the port's refusal is a `RenderError`.
 */
export const REFUSED_OPTIONS: ReadonlyArray<readonly [unknown, string]> = [
  [{ options: { base: 3 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: 0 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: 1 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: -16 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: 32 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: 16.5 } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: true } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: false } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: [16] } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { base: 3, basePrefix: "x" } }, "Plurimath::Errors::UnsupportedBase"],
  [{ options: { hexCapital: 1 } }, "Plurimath::ConfigurationError"],
  [{ options: { hexCapital: 1.5 } }, "Plurimath::ConfigurationError"],
  [{ options: { base: 16, basePrefix: true } }, "Plurimath::ConfigurationError"],
  [{ options: { base: 16, basePostfix: false } }, "Plurimath::ConfigurationError"],
  [{ options: { base: 10, basePrefix: true } }, "Plurimath::ConfigurationError"],
];
